-- risk_db_load.sql   (MySQL / MySQL Workbench)
-- ONE script: creates the database risk_db, the 6 tables, and loads all your data.
-- Data = your Risk_Analysis_Project.xlsx (cleaned tables + the formula columns you added in Excel).
-- Safe to re-run: it drops and rebuilds risk_db each time.
--
-- Tables
--   business_units(5)  customers(250)  invoices(2,688)  purchases(1,500)
--   treasury_monthly(119)  market_prices(1,563)

SET NAMES utf8mb4;
DROP DATABASE IF EXISTS risk_db;
CREATE DATABASE risk_db;
USE risk_db;

CREATE TABLE business_units (
    bu_id                      VARCHAR(10)   NOT NULL,
    bu_name                    VARCHAR(60)   NOT NULL,
    primary_product            VARCHAR(80),
    target_hedge_ratio         DECIMAL(4,2),
    hedging_policy             VARCHAR(200),
    sanctioned_credit_line_inr DECIMAL(18,2),
    PRIMARY KEY (bu_id)
);

CREATE TABLE customers (
    customer_id        VARCHAR(10)  NOT NULL,
    customer_name      VARCHAR(100) NOT NULL,
    country            VARCHAR(30),
    billing_currency   CHAR(3),
    industry           VARCHAR(40),
    credit_rating      VARCHAR(10),
    credit_limit_inr   DECIMAL(18,2),
    onboarding_date    DATE,
    limit_flag         VARCHAR(30),
    payment_terms_days INT,
    PRIMARY KEY (customer_id)
);

CREATE TABLE invoices (
    invoice_id         VARCHAR(12)   NOT NULL,
    customer_id        VARCHAR(10)   NOT NULL,
    bu_id              VARCHAR(10)   NOT NULL,
    invoice_date       DATE          NOT NULL,
    due_date           DATE          NOT NULL,
    currency           CHAR(3)       NOT NULL,
    invoice_amount     DECIMAL(18,2) NOT NULL,   -- in the invoice currency
    paid_date          DATE,
    status             VARCHAR(20),              -- PAID / OPEN / PARTIALLY PAID / WRITTEN OFF
    hedged_flag        CHAR(1),
    hedge_rate         DECIMAL(10,4),
    amount_paid        DECIMAL(18,2),            -- in the invoice currency
    fx_rate_inv        DECIMAL(12,4),            -- Excel: INR per unit of currency on invoice date
    invoice_amount_inr DECIMAL(18,2),            -- Excel: invoice value in rupees
    open_balance_inr   DECIMAL(18,2),            -- Excel: still owed, in rupees
    days_overdue       INT,                      -- Excel: days past due at 31-Mar-2025 (open balances)
    days_late          INT,                      -- Excel: paid date minus due date (paid invoices)
    aging_bucket       VARCHAR(15),              -- Excel: Not open / Not yet due / 1-30 / 31-60 / 61-90 / 90+
    PRIMARY KEY (invoice_id),
    KEY idx_inv_customer (customer_id),
    KEY idx_inv_bu (bu_id),
    CONSTRAINT fk_inv_customer FOREIGN KEY (customer_id) REFERENCES customers (customer_id),
    CONSTRAINT fk_inv_bu       FOREIGN KEY (bu_id)       REFERENCES business_units (bu_id)
);

CREATE TABLE purchases (
    purchase_id          VARCHAR(12)   NOT NULL,
    purchase_date        DATE          NOT NULL,
    bu_id                VARCHAR(10)   NOT NULL,
    currency             CHAR(3),
    quantity             INT,
    unit                 VARCHAR(10),
    total_amount         DECIMAL(18,2),          -- in the purchase currency
    hedged_flag          CHAR(1),
    hedge_price          DECIMAL(12,2),
    material             VARCHAR(40),
    unit_price           DECIMAL(12,2),
    payment_date         DATE,
    total_amount_inr     DECIMAL(18,2),          -- Excel: purchase value in rupees
    days_to_pay_supplier INT,                    -- Excel: payment date minus purchase date
    PRIMARY KEY (purchase_id),
    KEY idx_pur_bu (bu_id),
    CONSTRAINT fk_pur_bu FOREIGN KEY (bu_id) REFERENCES business_units (bu_id)
);

CREATE TABLE treasury_monthly (
    treasury_id             VARCHAR(10)   NOT NULL,
    bu_id                   VARCHAR(10)   NOT NULL,
    month_end               DATE          NOT NULL,
    opening_cash            DECIMAL(18,2),
    cash_inflows            DECIMAL(18,2),
    cash_outflows           DECIMAL(18,2),
    net_borrowing           DECIMAL(18,2),
    inventory               DECIMAL(18,2),
    trade_receivables       DECIMAL(18,2),
    current_assets          DECIMAL(18,2),
    current_liabilities     DECIMAL(18,2),
    short_term_debt_due_30d DECIMAL(18,2),
    undrawn_credit_line     DECIMAL(18,2),
    closing_cash            DECIMAL(18,2),
    PRIMARY KEY (treasury_id),
    UNIQUE KEY uq_treasury (bu_id, month_end),
    CONSTRAINT fk_tr_bu FOREIGN KEY (bu_id) REFERENCES business_units (bu_id)
);

CREATE TABLE market_prices (
    price_id        VARCHAR(10)   NOT NULL,
    price_date      DATE          NOT NULL,        -- the sheet column "date"
    asset           VARCHAR(20)   NOT NULL,
    asset_class     VARCHAR(15),
    price           DECIMAL(12,4),
    unit            VARCHAR(25),
    source          VARCHAR(120),
    carried_forward VARCHAR(3),
    PRIMARY KEY (price_id),
    UNIQUE KEY uq_price (asset, price_date)
);


-- ---------------- DATA ----------------







SELECT 'risk_db loaded' AS message;
